import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import squizInfoMock from "@ntgovernment/squiz-factory/plugins/squizInfo.mock";
import comp from "./main.js";

const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Side Navigation",
};

/**
 * The component resolves the current page itself first (via
 * `info.ctx.assetId` + `fns.resolveUri`), reads `sidebar_parent`/
 * `sidebar_current_asset` off its metadata, then resolves the parent the
 * same way for the back link -- no editor-picked or template-populated
 * input fields at all now (see side-navigation.spec.md assumption 7). The
 * sibling list and the current page's own nested children still come from
 * a plain fetch() against info.env.CONTENT_API_URL -- squizInfoMock only
 * mocks info.fns, so this stubs the global fetch instead. The mock is
 * `rootId`-aware, since main.js calls the same feed twice with two
 * different root IDs (the parent, for siblings; the current page, for its
 * own nested sub-pages).
 */
const FAKE_ASSETS_BY_ID = {
  5002: {
    id: "5002",
    metadata: { sidebar_parent: ["5001"], sidebar_current_asset: ["5002"] },
  },
  5003: {
    id: "5003",
    metadata: { sidebar_parent: ["5001"], sidebar_current_asset: ["5003"] },
  },
  9999: {
    id: "9999",
    metadata: { sidebar_parent: ["5001"], sidebar_current_asset: ["9999"] },
  },
  5001: {
    id: "5001",
    name: "Section page",
    short_name: "Section page",
    url: "https://example.com/section-page",
    metadata: {},
  },
};

const FAKE_SIBLINGS = [
  { id: "5002", name: "Sub-page one", url: "https://example.com/section-page/sub-page-one" },
  { id: "5003", name: "Sub-page two", url: "https://example.com/section-page/sub-page-two" },
  { id: "5004", name: "Sub-page three", url: "https://example.com/section-page/sub-page-three" },
  { id: "5005", name: "Sub-page four", url: "https://example.com/section-page/sub-page-four" },
];

const FAKE_NESTED_CHILDREN = [
  { id: "5006", name: "Nested page one", url: "https://example.com/section-page/sub-page-two/nested-page-one" },
  { id: "5007", name: "Nested page two", url: "https://example.com/section-page/sub-page-two/nested-page-two" },
];

const CHILDREN_BY_ROOT_ID = {
  5001: FAKE_SIBLINGS,
  5003: FAKE_NESTED_CHILDREN,
  // Used by the NoCurrentPageMatch story -- a stand-in "section" id with
  // siblings but no current-page match.
  9999: FAKE_SIBLINGS,
};

const FAKE_CONTENT_API_URL = "https://fake-content-api.example/child-list";

const realFetch = globalThis.fetch?.bind(globalThis);
globalThis.fetch = async (url, ...rest) => {
  if (typeof url === "string" && url.startsWith(FAKE_CONTENT_API_URL)) {
    const rootId = new URL(url).searchParams.get("rootId");
    return { ok: true, json: async () => CHILDREN_BY_ROOT_ID[rootId] ?? [] };
  }
  return realFetch(url, ...rest);
};

function mockInfoFor(currentAssetId) {
  const info = squizInfoMock({
    ctx: { assetId: currentAssetId },
    mock: {
      resolveUri: (uri) => {
        const id = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)/.exec(String(uri ?? ""))?.[1];
        return { ok: true, data: FAKE_ASSETS_BY_ID[id] ?? null };
      },
    },
  });
  return { ...info, env: { ...info.env, CONTENT_API_URL: FAKE_CONTENT_API_URL } };
}

const args = {};
const defaultInfo = mockInfoFor("5002");
const defaultHtml = await squiz.markup(args, defaultInfo);

export const Default = {
  render: () => squiz(args, defaultInfo),
  parameters: {
    docs: {
      description: { story: "The current page (\"Sub-page one\") is highlighted -- bold, with a left border accent, rendered as non-interactive text rather than a link. It has no sub-pages of its own here, so nothing is nested beneath it." },
      source: { code: defaultHtml, language: "html", type: "code" },
    },
  },
};

const nestedInfo = mockInfoFor("5003");
const nestedHtml = await squiz.markup(args, nestedInfo);

export const WithNestedSubPages = {
  render: () => squiz(args, nestedInfo),
  parameters: {
    docs: {
      description: { story: "The current page (\"Sub-page two\") has its own sub-pages -- they render nested, indented, directly beneath it in the list." },
      source: { code: nestedHtml, language: "html", type: "code" },
    },
  },
};

const noCurrentInfo = mockInfoFor("9999");
const noCurrentHtml = await squiz.markup(args, noCurrentInfo);

export const NoCurrentPageMatch = {
  render: () => squiz(args, noCurrentInfo),
  parameters: {
    docs: {
      description: { story: "sidebar_current_asset doesn't match any child's id (e.g. this component placed on a page outside the section) -- the full list still renders, just with nothing highlighted." },
      source: { code: noCurrentHtml, language: "html", type: "code" },
    },
  },
};

const unresolvableInfo = squizInfoMock({
  ctx: { assetId: "no-metadata" },
  mock: { resolveUri: () => ({ ok: true, data: null }) },
});
const unresolvableHtml = await squiz.markup(args, unresolvableInfo);

export const CurrentPageUnresolvable = {
  render: () => squiz(args, unresolvableInfo),
  parameters: {
    docs: {
      description: { story: "The current page itself fails to resolve via fns.resolveUri (e.g. resolveMatrixAssetById-style auth issue) -- no sidebar_parent/sidebar_current_asset can be read, so the component renders an empty nav rather than throwing." },
      source: { code: unresolvableHtml, language: "html", type: "code" },
    },
  },
};
